function GlassShearSpringMaker.init() GlassShearSpringMaker.ironStock=18; GlassShearSpringMaker.bronzeStock=14; GlassShearSpringMaker.woodStock=10; GlassShearSpringMaker.leatherStock=8; GlassShearSpringMaker.silverStock=8; GlassShearSpringMaker.goldStock=6; GlassShearSpringMaker.jewelStock=4; GlassShearSpringMaker.pearlStock=4; GlassShearSpringMaker.productStock={}; GlassShearSpringMaker.buildings={}; GlassShearSpringMaker.maker=nil; GlassShearSpringMaker.activeMaking={}; GlassShearSpringMaker.totalProducts=0; GlassShearSpringMaker.dayTimer=0; print("[GlassShearSpringMaker] Royal Glass Shear Spring Maker System initialized (6 products, 4 buildings)") end
function GlassShearSpringMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassShearSpringMaker.maker={name=n or ("Vzmetnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzmetnik najet: %s (spretnost: %d)",GlassShearSpringMaker.maker.name,s),"success") end; return true end
function GlassShearSpringMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassShearSpringMaker.build(id) local ok,e=GlassShearSpringMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassShearSpringMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassShearSpringMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassShearSpringMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassShearSpringMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassShearSpringMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassShearSpringMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassShearSpringMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassShearSpringMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassShearSpringMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassShearSpringMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassShearSpringMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassShearSpringMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassShearSpringMaker.buildings==0 then return false,"Potrebna vzmetna delavnica" end; if not GlassShearSpringMaker.maker then return false,"Potreben vzmetnik" end; return true end
function GlassShearSpringMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassShearSpringMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassShearSpringMaker.ironStock=GlassShearSpringMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassShearSpringMaker.bronzeStock=GlassShearSpringMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassShearSpringMaker.woodStock=GlassShearSpringMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassShearSpringMaker.leatherStock=GlassShearSpringMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassShearSpringMaker.silverStock=GlassShearSpringMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassShearSpringMaker.goldStock=GlassShearSpringMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassShearSpringMaker.jewelStock=GlassShearSpringMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassShearSpringMaker.pearlStock=GlassShearSpringMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassShearSpringMaker.maker then t=math.max(1,t-math.floor(GlassShearSpringMaker.maker.skill/13)) end; table.insert(GlassShearSpringMaker.activeMaking,{id="glassshearspring_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassShearSpringMaker.completeMaking(m) local q=1.0+(GlassShearSpringMaker.getQualityBonus()/100); if GlassShearSpringMaker.maker then q=q+(GlassShearSpringMaker.maker.skill/140) end; q=math.min(2.5,q); GlassShearSpringMaker.productStock[m.productType]=(GlassShearSpringMaker.productStock[m.productType] or 0)+m.quantity; GlassShearSpringMaker.totalProducts=GlassShearSpringMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassShearSpringMaker.maker then GlassShearSpringMaker.maker.itemsMade=GlassShearSpringMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassShearSpringMaker.maker.skill=math.min(100,GlassShearSpringMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzmet izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassshearspring.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassShearSpringMaker.update(dt) if not _G.state then return end; GlassShearSpringMaker.dayTimer=GlassShearSpringMaker.dayTimer+dt; if GlassShearSpringMaker.dayTimer>=30 then GlassShearSpringMaker.dayTimer=0; for i=#GlassShearSpringMaker.activeMaking,1,-1 do local m=GlassShearSpringMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassShearSpringMaker.completeMaking(m); table.remove(GlassShearSpringMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassShearSpringMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassShearSpringMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassShearSpringMaker.getStats() return {ironStock=GlassShearSpringMaker.ironStock,bronzeStock=GlassShearSpringMaker.bronzeStock,woodStock=GlassShearSpringMaker.woodStock,leatherStock=GlassShearSpringMaker.leatherStock,silverStock=GlassShearSpringMaker.silverStock,goldStock=GlassShearSpringMaker.goldStock,jewelStock=GlassShearSpringMaker.jewelStock,pearlStock=GlassShearSpringMaker.pearlStock,productStock=GlassShearSpringMaker.productStock,numBuildings=#GlassShearSpringMaker.buildings,hasMaker=GlassShearSpringMaker.maker~=nil,makerName=GlassShearSpringMaker.maker and GlassShearSpringMaker.maker.name or "—",makerSkill=GlassShearSpringMaker.maker and GlassShearSpringMaker.maker.skill or 0,activeMaking=#GlassShearSpringMaker.activeMaking,totalProducts=GlassShearSpringMaker.totalProducts} end
